		{"ctx ..", ".."},
	}
	for _, c := range cases {
		t.Run(c.line, func(t *testing.T) {
			a := argRouter(t)
			home, _ := os.UserHomeDir()
			parent := filepath.Dir(home)
			beforeHome := snapshotTree(t, home)
